/* Shared secure-link emails: Figma 280:346, 267:274 and 280:784. */
const secureEmailBase={page:mailboxPage,messages:mailboxMessages,people:mailboxPeople,handle,overlay:renderOverlay};
function emailGuestRecord(person=mailboxPerson()){return state.pickup?.reservations.find(r=>r.guest.email===person.email)||(state.pickup?organizerPaidGuest(roomSlots().find(s=>s.guest?.email===person.email&&s.payer==='Organizer')):null);}
function guestEmailToken(r){return r.guest.email==='priya@horizon.example'?'PN-3C8F-91AB':r.guest.first.charAt(0).toUpperCase()+r.guest.last.charAt(0).toUpperCase()+'-'+r.id+'-CV';}
function secureEmailCard(m){
 const person=mailboxPerson(),r=emailGuestRecord(person),organizer=person.role==='Organizer',invitation=m.id==='room-invite',code=m.id==='code';
 const features=organizer?['Group overview','Room allocation and guest list','BEO and contract','Invoices, deposit and balance','Schedule and meals','Share the group code and invite guests']:['My stay and room','Payment and receipt','Schedule and documents','Charges','Activities, meals, shuttle and extras'];
 const link=organizer?'cedarvalley.example/portal/o/HZN-7Q4M-2K9X':r?'cedarvalley.example/portal/g/'+guestEmailToken(r):'cedarvalley.example/group/GBR-008';
 const greeting=organizer?state.request.first: r?.guest.first||person.name.split(' ')[0];
 const body=m.id==='confirmed'?'Your booking is confirmed. Use the same private link as before to assign rooms, invite guests and see invoices, documents and the schedule. No account or password is needed.':m.id==='receipt'?'Use this private link to see your room, schedule, documents and charges, and to add activities. No account or password is needed: the link is unique to you.':invitation?name()+' reserved a room for you at the '+state.request.organization+' retreat. Confirm it and pay for your own room at the group rate.':m.body;
 let content='<h2>Hi '+esc(greeting)+',</h2><p>'+esc(body)+'</p>';
 if(invitation){content+='<div class="secure-email-details"><div>'+detail('Room',esc(r.type))+detail('Stay',dates()+' · '+nights()+' nights')+'</div><div>'+detail('Group rate',money(roomRate(r.type))+' per night')+detail('Total to pay',money(r.amount)+' including taxes')+'</div></div><div class="secure-email-hold"><b>Your room is held until Oct 30, 2026</b><span>After that date it returns to the group.</span></div><div class="secure-email-buttons">'+button('I can’t attend','email-decline-'+r.id)+button('Confirm and pay',m.action,'primary')+'</div>';}
 else {content+='<div class="secure-email-action">'+button(m.cta,m.action,'primary')+'<button class="secure-email-link" data-action="'+m.action+'">'+esc(link)+'</button></div>';
 if(!code&&m.id!=='declined')content+='<div class="secure-email-features"><b>What you can do</b>'+features.map(text=>'<div>'+img('9444f.svg')+'<span>'+text+'</span></div>').join('')+'</div>';
 content+='<small>This link is private to you, so there is nothing to log in to. Please do not forward it.</small>';}
 return '<div class="secure-email-design"><div class="quote-mail-subject"><b>'+esc(m.subject)+'</b><span>· Cedar Valley Retreat & Conference Center'+(invitation?' · Sep 26, 2026':'')+'</span></div><article class="secure-email-card"><header><small>'+(invitation?'ROOM INVITATION':code?'GROUP INVITATION':'SECURE LINK')+'</small><h3>'+esc(state.request.group)+'</h3></header><div class="secure-email-body">'+content+'</div></article></div>';
}
mailboxPeople=function(){const people=secureEmailBase.people();for(const p of Object.values(state.pickup?.declinedEmailGuests||{}))if(!people.some(x=>x.email===p.email))people.push(p);return people;};
mailboxMessages=function(){const declined=state.pickup?.declinedEmailGuests?.[mailboxPerson().email];if(declined&&!emailGuestRecord())return [{id:'declined',subject:'Room invitation declined',preview:'Your held room has been returned to the group.',body:'Your invitation has been declined and the held room returned to the group. Contact your organizer if your plans change.',cta:'Back to inbox',action:'mail-inbox'}];return secureEmailBase.messages().filter(m=>m.id!=='portal').map(m=>m.id==='confirmed'?{...m,subject:'Your event portal is open for rooms and guests',cta:'Open event portal'}:m.id==='receipt'?{...m,subject:'Your stay portal is ready',cta:'Open my stay'}:m.id==='room-invite'?{...m,subject:name()+' reserved a room for you',cta:'Confirm and pay'}:m);};
mailboxPage=function(){let html=secureEmailBase.page();const m=mailboxMessages().find(x=>x.id===state.ui.mailMessage);if(!m||m.id==='quote')return html;return html.replace(/<div class="gmail-email-card">[\s\S]*?<\/div><\/article>/,secureEmailCard(m)+'</article>').replace('bookings@cedarvalley.example','retreats@cedarvalley.example').replace('<small>Sep 22, 2026</small>',m.id==='room-invite'?'<small>Sep 26, 2026</small>':'<small>Sep 22, 2026</small>');};
handle=function(a,el){if(a.startsWith('email-decline-')){const r=individualById(a.slice(14));if(!r||r.paid)return;state.ui.emailDeclineId=r.id;modal='email-decline';renderOverlay();return;}if(a==='email-confirm-decline'){const r=individualById(state.ui.emailDeclineId);if(!r||r.paid)return;const person=mailboxPerson(),slot=slotById(r.slotId);(pickup().declinedEmailGuests??={})[person.email]={...person};if(slot){Object.assign(slot,{guest:null,payer:null,status:'Open',invited:false});delete slot.guestPortal;}pickup().reservations=pickup().reservations.filter(x=>x.id!==r.id);pickup().inviteQueue=pickup().inviteQueue.filter(id=>id!==r.slotId);if(pickup().invitedSlot===r.slotId)pickup().invitedSlot=null;modal=null;state.ui.mailMessage='declined';save();render();toast('Invitation declined. Your room was returned to the group.');return;}return secureEmailBase.handle(a,el);};
renderOverlay=function(){if(modal!=='email-decline')return secureEmailBase.overlay();$('#overlay').innerHTML='<div class="modal-backdrop"><section class="modal small guest-modal" role="dialog" aria-modal="true" aria-label="Decline room invitation"><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button><header class="modal-header">Decline room invitation?</header><div class="modal-content">Your held room will return to the group. You will not be charged.</div><footer class="modal-footer">'+button('Keep invitation','close-modal')+button('Decline invitation','email-confirm-decline','primary')+'</footer></section></div>';document.body.style.overflow='hidden';};
render();
